from pathlib import Path
import json,base64,html,sys
r=Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).parent
live=json.loads((r/'live/results.json').read_text());release=json.loads((r/'release.json').read_text());esc=lambda s:html.escape(str(s),quote=True)
assert all(not e['errors'] and len(e['checks'])==15 and all(c['pass'] for c in e['checks']) for e in live['engines'])
doc='''<!doctype html><html lang="en-GB"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Timber — live questionnaire repair</title><style>*{box-sizing:border-box}body{background:#050505;color:#e7e3da;font:16px/1.5 system-ui,sans-serif;margin:0}main{max-width:1160px;margin:auto;padding:24px}a{color:inherit}h1,h2{line-height:1.15}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #707762;vertical-align:top}.notice{padding:18px;border:1px solid #707762;border-radius:12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}figure{margin:0;border:1px solid #707762;border-radius:12px;overflow:hidden}figcaption{padding:12px}img{display:block;width:100%;height:auto}small{display:block;color:#bbb}code{overflow-wrap:anywhere}.table{overflow:auto}</style><main>'''
doc+='<h1>The written questionnaire is live and working</h1><p>Deployed <b>4 November 2026, 20:29 GMT</b>; live verification completed at 20:29:40 GMT.</p><p><a href="https://shiftsometimber.co.uk/member/dashboard/explore-weight-loss/questions?mt-rollback=1">Open the corrected health questions →</a></p>'
doc+='<div class="notice"><b>What changed</b><p>The app previously blocked all questions when the external provider was unavailable. The existing written question set now opens inside the shared app frame, saves privately, resumes after closing and can be completed and edited. The current medicine catalogue is available only after the written questions are complete.</p><b>Clinical boundary</b><p>This is a saved written questionnaire, not a prescription, eligibility approval or a completed clinical assessment. Provider submission and secure pharmacy image upload still require the provider connection. Images are not uploaded or persisted by this questionnaire. Payment stays disabled. No live payment, real member, provider submission or message was used in verification.</p></div>'
doc+='<h2>Verified results</h2><ul><li>Production: 15/15 conditions in Chromium and 15/15 in WebKit.</li><li>Hosted test site: the same 30/30 questionnaire conditions.</li><li>50/50 unit/model/database tests, including consent, account isolation, retry idempotency, stale devices, adult boundary and actual existing health erasure.</li><li>The three existing V7 journeys rerun: 52/52 conditions across Chromium and WebKit.</li></ul><p>Browser profiles: 390 × 844, 2×, touch/mobile emulation on the Mac. These are not physical iPhone or Android recordings. The two live navigation recordings and raw results are retained with the release evidence.</p>'
doc+='<div class="table"><table><tr><th>Engine</th><th>Condition</th><th>Result</th></tr>'
for e in live['engines']:
 for c in e['checks']:doc+='<tr><td>'+esc(e['name'])+'</td><td>'+esc(c['id'])+'</td><td>PASS</td></tr>'
doc+='</table></div><h2>Actual live screenshots</h2><p>Owned synthetic account: v7-live-proof@example.invalid, 900710301. Every image below was captured from production. These are not mockups.</p><div class="grid">'
names={'question-1':'Question 1 · private saving consent','question-2':'Question 2 · height and weight','review':'Review written answers','saved':'Written answers saved','options':'Existing catalogue, after questions'}
for e in live['engines']:
 for file in e['shots']:
  p=r/'live'/file
  if not p.exists():continue
  label=names.get(file[len(e['name'])+1:-4],file);uri='data:image/jpeg;base64,'+base64.b64encode(p.read_bytes()).decode()
  doc+='<figure><figcaption>'+esc(label)+'<small>'+esc(e['name'])+' · actual production</small></figcaption><img src="'+uri+'" alt="'+esc(label)+'"></figure>'
doc+='</div><h2>Release and rollback</h2><p>Live version: <code>'+esc(release['candidate'])+'</code><br>Source: <code>'+esc(release['source'])+'</code><br>Previous exact member version: <code>'+esc(release['base'])+'</code>.</p><p>One-step rollback: <code>node member-experience/tools/assessment-release.mjs rollback</code>. Core, payment, provider and supplier configuration were preserved.</p><p>The speed investigation was parked when Matt prioritised the broken questionnaire. Earlier timing runs are not presented as measurements of this new live version. This report supersedes the earlier closed-questionnaire screenshots for the written-question flow; it does not mark the whole clinical brief complete.</p></main></html>'
(r/'My-Timber-Questionnaire-LIVE.html').write_text(doc)
print(json.dumps({'liveChecks':sum(len(e['checks'])for e in live['engines']),'screens':sum(len(e['shots'])for e in live['engines']),'version':release['candidate'],'reportBytes':len(doc.encode())}))
